// Remembers when each phone number last submitted (stored in the workflow's static data)
// and flags a repeat within 24 hours.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const WINDOW_MS = 24 * 60 * 60 * 1000;
const now = Date.now();

return $input.all().map(item => {
  const body = item.json.body || item.json;
  const phone = String(body.phone || '').replace(/\D/g, '').slice(-10);
  if (phone.length !== 10) {
    return { json: { phone, valid: false, duplicate: false } };
  }
  const last = store.seen[phone];
  const duplicate = Boolean(last && now - last < WINDOW_MS);
  store.seen[phone] = now;
  return { json: { phone, valid: true, duplicate, last_seen: last ? new Date(last).toISOString() : null } };
});
